import{_ as r,a0 as l,w as p,s,ao as u,I as i,x as e,a1 as a,A as o}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const f=JSON.parse('{"title":"Linux 有问必答：如何在 Linux 上自动设置 JAVA_HOME 环境变量 | LCTT x X-CMD","titleTemplate":false,"description":"Linux 有问必答：如何在 Linux 上自动设置 JAVA_HOME 环境变量 | LCTT (201511) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Linux 有问必答：如何在 Linux 上自动设置 JAVA_HOME 环境变量 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Linux 有问必答：如何在 Linux 上自动设置 JAVA_HOME 环境变量 | LCTT (201511) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201511/20151116 Linux FAQs with Answers--How to set JAVA_HOME environment variable automatically on Linux","title":"Linux 有问必答：如何在 Linux 上自动设置 JAVA_HOME 环境变量","tag":"201511","desc":""},"relativePath":"201511/20151116 Linux FAQs with Answers--How to set JAVA_HOME environment variable automatically on Linux.md","filePath":"[post].md"}'),m={name:"201511/20151116 Linux FAQs with Answers--How to set JAVA_HOME environment variable automatically on Linux.md"};function A(x,t,J,d,v,_){const n=l("Link");return p(),s("div",null,[t[16]||(t[16]=u(`<h1 id="linux-有问必答-如何在-linux-上自动设置-java-home-环境变量" tabindex="-1">Linux 有问必答：如何在 Linux 上自动设置 JAVA_HOME 环境变量 <a class="header-anchor" href="#linux-有问必答-如何在-linux-上自动设置-java-home-环境变量" aria-label="Permalink to “Linux 有问必答：如何在 Linux 上自动设置 JAVA_HOME 环境变量”">​</a></h1><blockquote><p><strong>问题</strong>：我需要在我的 Linux 机器上编译 Java 程序。为此我已经安装了 JDK (Java Development Kit)，而现在我正试图设置 JAVA_HOME 环境变量使其指向安装好的 JDK 。关于在 Linux 上设置 JAVA_HOME 环境变量，最受推崇的办法是什么？</p></blockquote><p>许多 Java 程序或基于 Java 的<em>集成开发环境</em> (IDE)都需要设置好 JAVA_HOME 环境变量。该变量应指向 <em>Java 开发工具包</em> (JDK)或 <em>Java 运行时环境</em> (JRE)的安装目录。JDK 不仅包含了 JRE 提供的一切，还带有用于编译 Java 程序的额外的二进制代码和库文件（例如编译器，调试器及 JavaDoc 文档生成器）。JDK 是用来构建 Java 程序的，如果只是运行已经构建好的 Java 程序，单独一份 JRE 就足够了。</p><p>当您正试图设置 JAVA_HOME 环境变量时，麻烦的事情在于 JAVA_HOME 变量需要根据以下几点而改变：(1) 您是否安装了 JDK 或 JRE；(2) 您安装了哪个版本；(3) 您安装的是 Oracle JDK 还是 Open JDK。</p><p>因此每当您的开发环境或运行时环境发生改变（例如为 JDK 更新版本）时，您需要根据实际情况调整 JAVA_HOME 变量，而这种做法是繁重且缺乏效率的。</p><p>以下 export 命令能为您<strong>自动设置</strong> JAVA_HOME 环境变量，而无须顾及上述的因素。</p><p>若您安装的是 JRE：</p><pre><code>export JAVA_HOME=$(dirname $(dirname $(readlink -f $(which java))))
</code></pre><p>若您安装的是 JDK：</p><pre><code>export JAVA_HOME=$(dirname $(dirname $(readlink -f $(which javac))))
</code></pre><p>根据您的情况，将上述命令中的一条写入 ~/.bashrc（或 /etc/profile）文件中，它就会永久地设置好 JAVA_HOME 变量。</p><p>注意，由于 java 或 javac 可以建立起多个层次的符号链接，为此&quot;readlink -f&quot;命令是用来获取它们真正的执行路径的。</p><p>举个例子，假如您安装的是 Oracle JRE 7，那么上述的第一条 export 命令将自动设置 JAVA_HOME 为：</p><pre><code>/usr/lib/jvm/java-7-oracle/jre
</code></pre><p>若您安装的是 Open JDK 第8版，那么第二条 export 命令将设置 JAVA_HOME 为：</p><pre><code>/usr/lib/jvm/java-8-openjdk-amd64
</code></pre><p><img src="https://c1.staticflickr.com/1/700/22961948071_c73a3261dd_c.jpg" alt=""></p>`,17)),i("p",null,[t[1]||(t[1]=e("简而言之，这些 export 命令会在您重装/升级您的JDK/JRE，或",-1)),a(n,{href:"http://ask.xmodulo.com/change-default-java-version-linux.html"},{default:o(()=>[...t[0]||(t[0]=[e("更换默认 Java 版本",-1)])]),_:1}),t[2]||(t[2]=e("时自动更新 JAVA_HOME 变量。您不再需要手动调整它。",-1))]),t[17]||(t[17]=i("hr",null,null,-1)),i("p",null,[t[4]||(t[4]=e("via: ",-1)),a(n,{href:"http://ask.xmodulo.com/set-java_home-environment-variable-linux.html"},{default:o(()=>[...t[3]||(t[3]=[e("http://ask.xmodulo.com/set-java_home-environment-variable-linux.html",-1)])]),_:1})]),i("p",null,[t[8]||(t[8]=e("作者：",-1)),a(n,{href:"http://ask.xmodulo.com/author/nanni"},{default:o(()=>[...t[5]||(t[5]=[e("Dan Nanni",-1)])]),_:1}),t[9]||(t[9]=e(" 译者：",-1)),a(n,{href:"https://github.com/Ricky-Gong"},{default:o(()=>[...t[6]||(t[6]=[e("Ricky-Gong",-1)])]),_:1}),t[10]||(t[10]=e(" 校对：",-1)),a(n,{href:"https://github.com/wxy"},{default:o(()=>[...t[7]||(t[7]=[e("wxy",-1)])]),_:1})]),i("p",null,[t[13]||(t[13]=e("本文由 ",-1)),a(n,{href:"https://github.com/LCTT/TranslateProject"},{default:o(()=>[...t[11]||(t[11]=[e("LCTT",-1)])]),_:1}),t[14]||(t[14]=e(" 原创编译，",-1)),a(n,{href:"https://linux.cn/"},{default:o(()=>[...t[12]||(t[12]=[e("Linux中国",-1)])]),_:1}),t[15]||(t[15]=e(" 荣誉推出",-1))])])}const V=r(m,[["render",A]]);export{f as __pageData,V as default};
